    test('[TC_JSONPLACEHOLDER_PHOTOS_POST_003] Manage a photo end to end; as documented, changes are answered but not saved', async ({ api, data }) => {
      const input = data.entry('valid', 'TC_JSONPLACEHOLDER_PHOTOS_POST_003');
      // documented: this API simulates writes - verify the simulation contract
      // 1. create is answered as if it happened
      const created = await api.send({ method: 'POST', path: '/photos', identity: 'default', body: input.body });
      expectStatus(created, [201]);
      expectJsonContentType(created);
      expectResponseTime(created, limits.responseTimeMs);
      expectSchema(created, S.PhotosPostResponse);
      expectEcho(input.body, created.json);
      const createdId = getAtPath(created.json, 'id');
      expect(['string', 'number'], 'create response returns an id').toContain(typeof createdId);
      // 2. ...but nothing is persisted
      const notStored = await api.send({ method: 'GET', path: '/photos/{id}', identity: 'default', pathParams: { id: createdId as string | number } });
      expectStatus(notStored, [404]);
      // 3. updates and delete of an existing resource are answered as if they happened
      const id = await api.existingId('photos');
      const updated = await api.send({ method: 'PUT', path: '/photos/{id}', identity: 'default', pathParams: { id: id }, body: input.updateBody });
      expectStatus(updated, [200]);
      expectEcho(input.updateBody, updated.json);
      const patched = await api.send({ method: 'PATCH', path: '/photos/{id}', identity: 'default', pathParams: { id: id }, body: input.patchBody });
      expectStatus(patched, [200]);
      expectEcho(input.patchBody, patched.json);
      const removed = await api.send({ method: 'DELETE', path: '/photos/{id}', identity: 'default', pathParams: { id: id } });
      expectStatus(removed, [200,204]);
      // 4. the "deleted" resource is still there
      const still = await api.send({ method: 'GET', path: '/photos/{id}', identity: 'default', pathParams: { id: id } });
      expectStatus(still, [200]);
    });
